<?php
function component_definitions(int $productId): array {
    $q=db()->prepare('SELECT * FROM product_components WHERE product_id=? AND is_active=1 ORDER BY component_id');
    $q->execute([$productId]);
    $rows=$q->fetchAll();
    foreach($rows as &$row){
        $row['allowed_shapes']=json_decode($row['allowed_shapes_json'],true)?:[];
        $row['shape_prices']=json_decode($row['shape_prices_json'],true)?:[];
        $oq=db()->prepare('SELECT o.component_option_id,o.option_type,o.option_name,o.color_hex,o.texture_key,o.additional_cost,m.category material_category,m.roughness,m.metallic,m.normal_scale,m.base_color_map,m.normal_map,m.roughness_map,m.metallic_map,m.ao_map,m.preview_image FROM product_component_options o LEFT JOIN material_catalog m ON o.option_type="material" AND m.material_key=o.texture_key AND m.is_active=1 WHERE o.component_id=? AND o.is_active=1 ORDER BY o.option_type,o.option_name');
        $oq->execute([$row['component_id']]);
        $row['options']=$oq->fetchAll();

        // The local COVE 122 GLB exposes a walnut top, turned legs, a slatted shelf,
        // a walnut apron frame, and separate metal/brass/felt hardware groups. Restrict capabilities to
        // those actual groups; retain the existing database rows and price rules.
        if($productId===2){
            $key=$row['component_key'];
            $capabilities=[
                'table_top'=>['shape'=>'rounded','controls'=>['option_material','option_color','option_finish','custom_color'],'materials'=>['wood','surface']],
                'table_leg'=>['shape'=>'tapered','controls'=>['option_material','option_color','option_finish','custom_color'],'materials'=>['wood']],
                'table_brace'=>['shape'=>'rectangular','controls'=>['option_material','option_color','option_finish','custom_color'],'materials'=>['wood']],
                'table_frame'=>['shape'=>'rectangular','controls'=>['option_material','option_color','option_finish','custom_color'],'materials'=>['wood']],
                'table_hardware'=>['shape'=>'bar','controls'=>['option_material','option_color','option_finish','custom_color'],'materials'=>['metal']],
            ];
            if(isset($capabilities[$key])){
                $cap=$capabilities[$key];
                $row['default_shape']=$cap['shape'];
                $row['allowed_shapes']=[$cap['shape']];
                $row['shape_prices']=[$cap['shape']=>0];
                $row['supported_controls']=$cap['controls'];
                $row['options']=array_values(array_filter($row['options'],static function($option)use($cap){
                    return $option['option_type']!=='material'||in_array($option['material_category']??'', $cap['materials'],true);
                }));


            }
        }elseif($productId===3){
            // Haven uses a finished CC0 bed GLB with real named mesh groups.
            // Keep its baked construction and placements intact; expose only
            // material and color changes on those genuinely separate groups.
            $categories=[
                'bed_frame'=>'wood','bed_ends'=>'wood','bed_legs'=>'wood',
                'bed_hardware'=>'metal','bed_mattress'=>'upholstery',
                'bed_pillows'=>'upholstery','bed_quilt'=>'upholstery','bed_folded_return'=>'upholstery',
            ];
            if(isset($categories[$row['component_key']])){
                $row['supported_controls']=['option_material'];
                $row['options']=array_values(array_filter($row['options'],static fn($option)=>$option['option_type']!=='material'||($option['material_category']??'')===$categories[$row['component_key']]));
            }
        }elseif($productId===1||$productId===4||$productId===5){
            $categories=$productId===1?['frame'=>['upholstery'],'left_arm'=>['upholstery'],'right_arm'=>['upholstery'],'backrest'=>['upholstery'],'seat_cushion'=>['upholstery'],'sofa_leg'=>['metal']]:($productId===4?['dining_top'=>['wood'],'dining_legs'=>['wood'],'dining_brace'=>['wood'],'dining_hardware'=>['metal'],'dining_extension_leaf'=>['wood'],'dining_foot_glides'=>['metal']]:['desk_top'=>['wood'],'desk_frame'=>['metal'],'desk_legs'=>['metal'],'desk_drawer'=>['wood'],'desk_drawer_front'=>['wood'],'desk_drawer_handle'=>['metal'],'desk_hardware'=>['metal']]);
            $key=$row['component_key'];if(isset($categories[$key])){$row['supported_controls']=$productId===4&&$key==='dining_foot_glides'?['custom_color']:['option_material','option_color','option_finish','custom_color'];$row['options']=array_values(array_filter($row['options'],static fn($option)=>$option['option_type']!=='material'||in_array($option['material_category']??'', $categories[$key],true)));$row['allowed_shapes']=[$row['default_shape']];$row['shape_prices']=[$row['default_shape']=>0];$row['min_quantity']=$row['max_quantity']=$row['default_quantity'];}
        }else{
            $row['supported_controls']=['shape','quantity','width_cm','depth_cm','height_cm','position_x','position_y','position_z','option_material','option_color','option_finish','custom_color'];
        }
        $controls=['custom_color'];
        foreach(['width','depth','height','x','y','z'] as $axis){
            if((float)$row['max_'.$axis.'_cm']>(float)$row['min_'.$axis.'_cm']){
                $controls[]=in_array($axis,['x','y','z'],true)?'position_'.$axis:$axis.'_cm';
            }
        }
        if($row['max_quantity']>$row['min_quantity'])$controls[]='quantity';
        if(count($row['allowed_shapes'])>1)$controls[]='shape';
        foreach(array_unique(array_column($row['options'],'option_type')) as $type)$controls[]='option_'.$type;
        $row['supported_controls']=$controls;

    }
    unset($row);
    return $rows;
}

function component_material_catalog(): array {return db()->query('SELECT material_key,material_name,category,color_hex,roughness,metallic,normal_scale,base_color_map,normal_map,roughness_map,metallic_map,ao_map,preview_image,additional_cost FROM material_catalog WHERE is_active=1 ORDER BY category,material_name')->fetchAll();}
function component_color_palette(): array {return db()->query('SELECT color_id,color_name,category,color_hex FROM color_palette_options WHERE is_active=1 ORDER BY category,color_name')->fetchAll();}

/** Validate the product-level dimensions and calculate their authoritative surcharge. */
function validate_overall_dimensions(PDO $pdo,int $productId,array $input,float $basePrice): array {
    $q=$pdo->prepare('SELECT * FROM product_dimension_rules WHERE product_id=? ORDER BY FIELD(dimension_name,"width","depth","height")');$q->execute([$productId]);$rules=$q->fetchAll();
    $allowed=[];$values=[];$lines=[];$extra=0.0;
    foreach($rules as $rule){$key=$rule['dimension_name'];$allowed[$key]=true;$raw=$input[$key]??null;$n=filter_var($raw,FILTER_VALIDATE_FLOAT);$min=(float)$rule['min_cm'];$max=(float)$rule['max_cm'];$step=(float)$rule['step_cm'];$base=(float)$rule['default_cm'];
        if($n===false||!is_finite((float)$n)||(float)$n<$min||(float)$n>$max||($step>0&&abs((((float)$n-$min)/$step)-round(((float)$n-$min)/$step))>0.00001))throw new RuntimeException('Enter each overall dimension within its allowed range and step.');
        $n=round((float)$n,2);$cost=0.0;$amount=(float)$rule['price_amount'];
        switch($rule['pricing_mode']){case 'per_cm':$cost=max(0,$n-$base)*$amount;break;case 'fixed':$cost=abs($n-$base)>.00001?$amount:0;break;case 'percentage':$cost=abs($n-$base)>.00001?$basePrice*$amount/100:0;break;case 'material_usage':$cost=ceil(max(0,$n-$base)/100)*$amount;break;case 'ranges':$rq=$pdo->prepare('SELECT additional_cost FROM product_dimension_price_ranges WHERE product_id=? AND dimension_name=? AND ? >= min_cm AND (? < max_cm OR (? = max_cm AND max_cm=(SELECT MAX(max_cm) FROM product_dimension_price_ranges WHERE product_id=? AND dimension_name=?)))');$rq->execute([$productId,$key,$n,$n,$n,$productId,$key]);$matches=$rq->fetchAll(PDO::FETCH_COLUMN);if(count($matches)!==1)throw new RuntimeException('This overall dimension does not match a configured price range.');$rq->execute([$productId,$key,$base,$base,$base,$productId,$key]);$defaultMatches=$rq->fetchAll(PDO::FETCH_COLUMN);if(count($defaultMatches)!==1)throw new RuntimeException('The product default does not match a configured price range.');$cost=max(0,(float)$matches[0]-(float)$defaultMatches[0]);break;}
        $values[$key]=$n;$extra+=$cost;$label=['width'=>'Overall Width','depth'=>'Overall Length / Depth','height'=>'Overall Height'][$key]??ucfirst($key);$lines[]=[$label.': '.number_format($n,1).' cm',$cost];
    }
    foreach(['width','depth','height'] as $key)if(array_key_exists($key,$input)&&!isset($allowed[$key]))throw new RuntimeException('This overall dimension is not configurable for this product.');
    return ['dimensions'=>$values,'lines'=>$lines,'additional_cost'=>round($extra,2),'rules'=>$rules];
}

function validate_component_submission(PDO $pdo,int $productId,string $raw): array {
    if(strlen($raw)>65536)throw new RuntimeException('Component configuration is too large.');$input=json_decode($raw,true);if(!is_array($input))throw new RuntimeException('Invalid component configuration. Please reload the configurator.');$defs=component_definitions($productId);if(count($defs)!==count($input))throw new RuntimeException('The component list changed. Reload the configurator before adding this item.');$byId=[];$byKey=[];foreach($defs as $d){$byId[(string)$d['component_id']]=$d;$byKey[$d['component_key']]=$d;}$canonical=[];$specLookup=[];$total=0.0;
    foreach($input as $id=>$s){$id=(string)$id;if(!isset($byId[$id])||!is_array($s))throw new RuntimeException('Unknown component submitted.');$d=$byId[$id];$allowed=$d['allowed_shapes'];$shape=(string)($s['shape']??'');if(!in_array($shape,$allowed,true))throw new RuntimeException('Unsupported shape for '.$d['display_name'].'.');$qty=filter_var($s['quantity']??null,FILTER_VALIDATE_INT);if($qty===false||$qty<(int)$d['min_quantity']||$qty>(int)$d['max_quantity'])throw new RuntimeException('Invalid quantity for '.$d['display_name'].'.');$dimIn=$s['dimensions']??[];$posIn=$s['position']??[];$dims=[];$pos=[];$axisNames=['width'=>['width_cm','default_width_cm','min_width_cm','max_width_cm','width_rate'],'depth'=>['depth_cm','default_depth_cm','min_depth_cm','max_depth_cm','depth_rate'],'height'=>['height_cm','default_height_cm','min_height_cm','max_height_cm','height_rate']];$one=0.0;foreach($axisNames as $axis=>$cols){$v=filter_var($dimIn[$cols[0]]??null,FILTER_VALIDATE_FLOAT);$v=$v===false?false:(float)$v;if($v===false||!is_finite($v)||$v<(float)$d[$cols[2]]||$v>(float)$d[$cols[3]])throw new RuntimeException('Invalid '.$axis.' for '.$d['display_name'].'.');$v=round($v,2);$dims[$cols[0]]=$v;$one+=abs($v-(float)$d[$cols[1]])*(float)$d[$cols[4]];}
        foreach(['x','y','z'] as $axis){$v=filter_var($posIn[$axis]??null,FILTER_VALIDATE_FLOAT);$v=$v===false?false:(float)$v;if($v===false||!is_finite($v)||$v<(float)$d['min_'.$axis.'_cm']||$v>(float)$d['max_'.$axis.'_cm'])throw new RuntimeException('Invalid position for '.$d['display_name'].'.');$pos[$axis]=round($v,2);}
        $shapePrice=(float)($d['shape_prices'][$shape]??0);$baseExtra=max(0,$qty-(int)$d['default_quantity'])*(float)$d['unit_price'];$one=($one+$shapePrice)*$qty+$baseExtra;$optionSpecs=[];$provided=$s['options']??[];foreach(['material','color','finish'] as $type){$oid=(int)($provided[$type]??0);$picked=null;if($oid){foreach($d['options'] as $o)if((int)$o['component_option_id']===$oid&&$o['option_type']===$type){$picked=$o;break;}if(!$picked)throw new RuntimeException('Invalid '.$type.' choice for '.$d['display_name'].'.');}
            if($picked){$optionSpecs[$type]=['name'=>$picked['option_name'],'color_hex'=>$picked['color_hex'],'texture_key'=>$picked['texture_key'],'material_category'=>$picked['material_category']??null,'roughness'=>isset($picked['roughness'])?(float)$picked['roughness']:null,'metallic'=>isset($picked['metallic'])?(float)$picked['metallic']:null,'normal_scale'=>isset($picked['normal_scale'])?(float)$picked['normal_scale']:null,'maps'=>$type==='material'?['base_color'=>$picked['base_color_map']??null,'normal'=>$picked['normal_map']??null,'roughness'=>$picked['roughness_map']??null,'metallic'=>$picked['metallic_map']??null,'ao'=>$picked['ao_map']??null]:null,'preview_image'=>$picked['preview_image']??null,'option_id'=>(int)$picked['component_option_id'],'unit_cost'=>(float)$picked['additional_cost']];$one+=(float)$picked['additional_cost']*$qty;}else{$defaults=['material'=>$d['default_material'],'color'=>'Default color','finish'=>$d['default_finish']];$optionSpecs[$type]=['name'=>$defaults[$type],'color_hex'=>$type==='color'?$d['default_color_hex']:null,'texture_key'=>$type==='material'?$d['default_texture_key']:'solid','option_id'=>null,'unit_cost'=>0.0];}}
        $customColor=trim((string)($s['custom_color']??''));if($customColor!==''&&!preg_match('/^#[0-9a-fA-F]{6}$/',$customColor))throw new RuntimeException('Invalid custom HEX color for '.$d['display_name'].'.');$customColor=$customColor===''?null:strtoupper($customColor);
        $spec=['component_id'=>(int)$d['component_id'],'component_key'=>$d['component_key'],'label'=>$d['display_name'],'geometry_type'=>$d['geometry_type'],'shape'=>$shape,'quantity'=>$qty,'dimensions'=>$dims,'position_cm'=>$pos,'custom_color'=>$customColor,'options'=>$optionSpecs];$canonical[$id]=['spec'=>$spec,'additional_cost'=>round($one,2)];$specLookup[$id]=$spec;$total+=$one;
    }
    foreach($defs as $d){$anchorKey=$d['anchor_component_key']??null;if(!$anchorKey||!isset($byKey[$anchorKey]))continue;$part=$specLookup[(string)$d['component_id']]??null;$hostDef=$byKey[$anchorKey];$host=$specLookup[(string)$hostDef['component_id']]??null;if(!$part||!$host)continue;if($host['quantity']<1&&$part['quantity']>0)throw new RuntimeException($d['display_name'].' requires at least one '.$hostDef['display_name'].'.');if($part['quantity']<1)continue;$axis=$d['layout_axis'];$pos=$part['position_cm'];$hostPos=$host['position_cm'];$widthFits=$part['dimensions']['width_cm']<=$host['dimensions']['width_cm']+.01;$depthFits=$part['dimensions']['depth_cm']<=$host['dimensions']['depth_cm']+.01;$heightFits=true;if($axis==='x'||$axis==='columns')$widthFits=$part['dimensions']['width_cm']*$part['quantity']+2*abs($pos['x']-(float)$d['default_x_cm'])<=$host['dimensions']['width_cm']+.01;elseif($axis==='y'||$axis==='shelves'){$offset=$axis==='shelves'?$pos['y']-(float)$d['default_y_cm']:$pos['y']-$hostPos['y'];$heightFits=$part['dimensions']['height_cm']*$part['quantity']+2*abs($offset)<=$host['dimensions']['height_cm']+.01;}elseif($axis==='z'||$axis==='spread_z')$depthFits=$part['dimensions']['depth_cm']*$part['quantity']+2*abs($pos['z']-(float)$d['default_z_cm'])<=$host['dimensions']['depth_cm']+.01;else{$xOffset=$axis==='corners'?$pos['x']:$pos['x']-$hostPos['x'];$zOffset=$axis==='corners'?$pos['z']:$pos['z']-$hostPos['z'];$widthFits=$part['dimensions']['width_cm']+2*abs($xOffset)<=$host['dimensions']['width_cm']+.01;$depthFits=$part['dimensions']['depth_cm']+2*abs($zOffset)<=$host['dimensions']['depth_cm']+.01;}if(!$widthFits||!$depthFits||!$heightFits)throw new RuntimeException('Combined '.$d['display_name'].' position and dimensions exceed its host component.');}
    if($productId===2&&isset($byKey['table_top'],$byKey['table_leg'])){$top=$specLookup[(string)$byKey['table_top']['component_id']]['dimensions'];$legs=$specLookup[(string)$byKey['table_leg']['component_id']]['dimensions'];if(.78*$top['width_cm']+$legs['width_cm']>$top['width_cm']+.01||(.6666667*$top['depth_cm'])+$legs['depth_cm']>$top['depth_cm']+.01)throw new RuntimeException('The selected leg size extends beyond the tabletop.');}
    return ['components'=>$canonical,'additional_cost'=>round($total,2)];
}

function format_component_snapshot(string $json): string { $data=json_decode($json,true);if(!is_array($data))return 'Component details unavailable.';$o=$data['options']??[];$d=$data['dimensions']??[];$p=$data['position_cm']??[];return ($data['label']??'Component').' × '.($data['quantity']??1).' · '.($data['shape']??'').sprintf(' · W %.1f × D %.1f × H %.1f cm · position X %.1f / Y %.1f / Z %.1f cm', (float)($d['width_cm']??0),(float)($d['depth_cm']??0),(float)($d['height_cm']??0),(float)($p['x']??0),(float)($p['y']??0),(float)($p['z']??0)).' · '.($o['material']['name']??'').', '.(($data['custom_color']??null) ?: ($o['color']['name']??'')).', '.($o['finish']['name']??''); }

function save_material_map_upload(string $field): ?string {
    if(empty($_FILES[$field])||($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;
    $file=$_FILES[$field];if(($file['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK||($file['size']??0)>5*1024*1024)throw new RuntimeException('Material maps must be valid image files under 5 MB.');
    $info=@getimagesize($file['tmp_name']);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!$info||!isset($extensions[$mime])||$info[0]>4096||$info[1]>4096)throw new RuntimeException('Upload a PNG, JPEG, or WebP map up to 4096 × 4096 pixels.');
    $dir=__DIR__.'/../uploads/materials';if(!is_dir($dir)&&!mkdir($dir,0750,true))throw new RuntimeException('Could not create the protected material upload folder.');$name=bin2hex(random_bytes(18)).'.'.$extensions[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Could not store the material image.');return 'uploads/materials/'.$name;
}

