    $pdo=db();
    switch($action){
      case 'material_catalog_save':
        require_role('admin');$key=strtolower(trim((string)($_POST['material_key']??'')));$name=trim((string)($_POST['material_name']??''));$category=(string)($_POST['category']??'');$hex=(string)($_POST['color_hex']??'');$rough=filter_var($_POST['roughness']??null,FILTER_VALIDATE_FLOAT);$metal=filter_var($_POST['metallic']??null,FILTER_VALIDATE_FLOAT);$normal=filter_var($_POST['normal_scale']??null,FILTER_VALIDATE_FLOAT);$cost=filter_var($_POST['additional_cost']??null,FILTER_VALIDATE_FLOAT);if(!preg_match('/^[a-z][a-z0-9_]{1,31}$/',$key)||$name===''||mb_strlen($name)>100||!in_array($category,['upholstery','wood','metal','surface'],true)||!preg_match('/^#[0-9a-fA-F]{6}$/',$hex)||$rough===false||$rough<0||$rough>1||$metal===false||$metal<0||$metal>1||$normal===false||$normal<0||$normal>2||$cost===false||$cost<0)throw new RuntimeException('Enter valid material properties, a supported category and a HEX color.');$old=$pdo->prepare('SELECT * FROM material_catalog WHERE material_key=?');$old->execute([$key]);$previous=$old->fetch()?:[];$maps=[];foreach(['base_color_map','normal_map','roughness_map','metallic_map','ao_map','preview_image'] as $field)$maps[$field]=save_material_map_upload($field)??($previous[$field]??null);$pdo->prepare('INSERT INTO material_catalog(material_key,material_name,category,color_hex,roughness,metallic,normal_scale,base_color_map,normal_map,roughness_map,metallic_map,ao_map,preview_image,additional_cost,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,1) ON DUPLICATE KEY UPDATE material_name=VALUES(material_name),category=VALUES(category),color_hex=VALUES(color_hex),roughness=VALUES(roughness),metallic=VALUES(metallic),normal_scale=VALUES(normal_scale),base_color_map=VALUES(base_color_map),normal_map=VALUES(normal_map),roughness_map=VALUES(roughness_map),metallic_map=VALUES(metallic_map),ao_map=VALUES(ao_map),preview_image=VALUES(preview_image),additional_cost=VALUES(additional_cost)')->execute([$key,$name,$category,strtoupper($hex),(float)$rough,(float)$metal,(float)$normal,$maps['base_color_map'],$maps['normal_map'],$maps['roughness_map'],$maps['metallic_map'],$maps['ao_map'],$maps['preview_image'],(float)$cost]);flash('Material library entry saved. Assign it to supported components from 3D Component Models.');redirect('?page=material-admin');
      case 'material_catalog_toggle':require_role('admin');$st=$pdo->prepare('UPDATE material_catalog SET is_active=1-is_active WHERE material_key=?');$st->execute([(string)($_POST['material_key']??'')]);if(!$st->rowCount())throw new RuntimeException('Material not found or availability did not change.');flash('Material availability updated.');redirect('?page=material-admin');
      case 'color_palette_save':require_role('admin');$name=trim((string)($_POST['color_name']??''));$category=trim((string)($_POST['category']??''));$hex=(string)($_POST['color_hex']??'');if($name===''||mb_strlen($name)>80||$category===''||mb_strlen($category)>32||!preg_match('/^#[0-9a-fA-F]{6}$/',$hex))throw new RuntimeException('Enter a color name, category and valid HEX value.');$pdo->prepare('INSERT INTO color_palette_options(color_name,category,color_hex) VALUES(?,?,?) ON DUPLICATE KEY UPDATE category=VALUES(category),is_active=1')->execute([$name,$category,strtoupper($hex)]);flash('Color palette entry saved.');redirect('?page=material-admin');
      case 'color_palette_toggle':require_role('admin');$st=$pdo->prepare('UPDATE color_palette_options SET is_active=1-is_active WHERE color_id=?');$st->execute([(int)($_POST['color_id']??0)]);if(!$st->rowCount())throw new RuntimeException('Color option not found or availability did not change.');flash('Color palette availability updated.');redirect('?page=material-admin');
      case 'customized_add_cart':
        $u=require_role('customer');$pid=(int)($_POST['product_id']??0);$p=product($pid);if(!$p||!$p['is_customizable']||$p['availability']!=='In Stock')throw new RuntimeException('This product is unavailable for customization.');
        $dimensionConfig=validate_overall_dimensions($pdo,$pid,$_POST,(float)$p['base_price']);$dims=$dimensionConfig['lines'];$extra=(float)$dimensionConfig['additional_cost'];
$globalOptions=(array)($_POST['options']??[]);$globalOptions=array_filter($globalOptions,static fn($optionId)=>$optionId!==''&&(string)$optionId!=='0');if($pid===2&&$globalOptions)throw new RuntimeException('Milo accepts only the supported per-component surface choices.');$selected=[];$byType=[];foreach((array)($_POST['options']??[]) as $optionId){if($optionId==='')continue;$oid=(int)$optionId;$q=$pdo->prepare('SELECT o.option_id,o.option_name,o.additional_cost,t.type_id,t.type_name FROM product_customization_options po JOIN customization_options o USING(option_id) JOIN customization_types t USING(type_id) WHERE po.product_id=? AND po.option_id=? AND o.is_active=1');$q->execute([$pid,$oid]);$o=$q->fetch();if(!$o||isset($byType[$o['type_id']]))throw new RuntimeException('Invalid or duplicate customization option. Refresh the product page and retry.');$byType[$o['type_id']]=true;$extra+=(float)$o['additional_cost'];$selected[]=[$oid,$o['type_name'].': '.$o['option_name'],(float)$o['additional_cost']];}
