        $qty=filter_var($_POST['quantity']??1,FILTER_VALIDATE_INT);if($qty===false||$qty<1||$qty>99)throw new RuntimeException('Quantity must be between 1 and 99.');$pdo->beginTransaction();$cart=active_cart((int)$u['user_id']);$q=$pdo->prepare('INSERT INTO cart_items(cart_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');$q->execute([$cart,$pid,$qty,(float)$p['base_price']+$extra]);$ci=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO cart_item_customizations(cart_item_id,option_id,selected_value,additional_cost) VALUES(?,?,?,?)');foreach($dims as [$label,$cost])$ins->execute([$ci,null,$label,$cost]);foreach($selected as [$oid,$label,$cost])$ins->execute([$ci,$oid,$label,$cost]);if($componentConfig){$snap=$pdo->prepare('INSERT INTO cart_item_component_snapshots(cart_item_id,component_key,component_label,spec_json,additional_cost) VALUES(?,?,?,?,?)');foreach($componentConfig['components'] as $item)$snap->execute([$ci,$item['spec']['component_key'],$item['spec']['label'],json_encode($item['spec'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),(float)$item['additional_cost']]);}$pdo->commit();flash('Customized item added to your cart.');redirect('?page=cart');
