      case 'reset_password':$raw=(string)($_POST['token']??'');$pw=(string)($_POST['password']??'');if(strlen($pw)<10)throw new RuntimeException('Password must contain at least 10 characters.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT reset_id,user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE');$q->execute([hash('sha256',$raw)]);$t=$q->fetch();if(!$t)throw new RuntimeException('Reset link invalid or expired.');$pdo->prepare('UPDATE users SET password_hash=?,auth_version=auth_version+1 WHERE user_id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$t['user_id']]);$pdo->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$t['user_id']]);$pdo->commit();unset($_SESSION['user_id'],$_SESSION['auth_version']);flash('Password changed. Please sign in.');redirect('?page=login');
    }
    return false;
}

function render_advanced_page(string $page): bool {
    $adminPages=['products-admin','categories-admin','customization-admin','component-admin','material-admin','reports','orders','order-admin-detail','users'];
    if(in_array($page,$adminPages,true))require_role('admin');
    if($page==='order'||$page==='my-orders')require_role('customer');
    if($page==='dashboard'){$u=require_login();if($u['role']==='admin'){$stats=db()->query('SELECT (SELECT COUNT(*) FROM products WHERE availability<>"Archived") products,(SELECT COUNT(*) FROM orders WHERE status IN ("Pending","Confirmed","Processing","Manufacturing")) open_orders,(SELECT COUNT(*) FROM custom_requests WHERE request_status NOT IN ("Accepted","Rejected","Cancelled")) open_requests,(SELECT COUNT(*) FROM quotations WHERE status="Sent") sent_quotes')->fetch();$links=['orders'=>'Order management','products-admin'=>'Products','categories-admin'=>'Categories','customization-admin'=>'Customization rules','component-admin'=>'3D Component Models','material-admin'=>'Material Library','requests'=>'Custom requests','users'=>'Users','quotations'=>'Quotations','reports'=>'Reports'];?><div><span class="eyebrow">FurniFlex control center</span><h1>Administrator dashboard</h1><p class="text-secondary">A live overview of your catalog and customer work.</p></div><div class="row g-3 my-3"><?php foreach(['products'=>'Catalog products','open_orders'=>'Orders in progress','open_requests'=>'Open custom requests','sent_quotes'=>'Sent quotations'] as $k=>$label):?><div class="col-6 col-lg-3"><div class="stat-card"><small><?=e($label)?></small><strong><?=$stats[$k]?></strong></div></div><?php endforeach;?></div><div class="row g-3"><?php foreach($links as $route=>$label):?><div class="col-12 col-sm-6 col-lg-4"><a class="dash-link" href="?page=<?=$route?>"><h2 class="h5"><?=e($label)?></h2><span>Manage <?=strtolower(e($label))?> →</span></a></div><?php endforeach;?></div><?php return true;}if($u['role']==='manufacturer'){$q=db()->prepare('SELECT COUNT(*) FROM custom_requests WHERE assigned_manufacturer_id=?');$q->execute([$u['user_id']]);$n=(int)$q->fetchColumn();?><span class="eyebrow">Design workshop</span><h1>Manufacturer workspace</h1><p>Review your assigned requests and share technical assessments.</p><div class="stat-card mb-3"><small>Assigned requests</small><strong><?=$n?></strong></div><a class="btn btn-primary" href="?page=requests">Open assigned requests</a> <a class="btn btn-outline-dark" href="?page=notifications">Notifications</a><?php return true;}return false;}
    if($page==='material-admin'){$materials=db()->query('SELECT * FROM material_catalog ORDER BY category,material_name')->fetchAll();$colors=db()->query('SELECT * FROM color_palette_options ORDER BY category,color_name')->fetchAll();?><div class="d-flex justify-content-between align-items-center"><div><span class="eyebrow">Catalog surfaces</span><h1>Material and color library</h1></div><a class="btn btn-outline-dark" href="?page=component-admin">3D components</a></div><p class="text-secondary">Manage local PBR material maps and reusable color swatches. Deactivating an option removes it from new customization selections without changing saved cart or order snapshots.</p><form class="card p-3 mb-4" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="material_catalog_save"><h2 class="h5">Add or update a material</h2><div class="row g-3"><div class="col-md-3"><label class="form-label">Key<input class="form-control" name="material_key" pattern="[a-z][a-z0-9_]{1,31}" required></label></div><div class="col-md-3"><label class="form-label">Name<input class="form-control" name="material_name" maxlength="100" required></label></div><div class="col-md-2"><label class="form-label">Category<select class="form-select" name="category"><option>wood</option><option>upholstery</option><option>metal</option><option>surface</option></select></label></div><div class="col-md-2"><label class="form-label">Base HEX<input class="form-control" name="color_hex" type="color" value="#a67c52" required></label></div><div class="col-md-2"><label class="form-label">Cost<input class="form-control" name="additional_cost" type="number" min="0" step=".01" value="0" required></label></div><?php foreach(['roughness'=>'Roughness','metallic'=>'Metallic','normal_scale'=>'Normal scale'] as $field=>$label):?><div class="col-md-2"><label class="form-label"><?=e($label)?><input class="form-control" name="<?=$field?>" type="number" min="0" max="<?=$field==='normal_scale'?'2':'1'?>" step=".01" value="<?=$field==='roughness'?'0.65':($field==='metallic'?'0':'1')?>" required></label></div><?php endforeach;?><?php foreach(['base_color_map'=>'Base color','normal_map'=>'Normal','roughness_map'=>'Roughness map','metallic_map'=>'Metallic map','ao_map'=>'Ambient occlusion','preview_image'=>'Preview'] as $field=>$label):?><div class="col-md-4"><label class="form-label"><?=e($label)?> texture<input class="form-control" type="file" name="<?=$field?>" accept="image/png,image/jpeg,image/webp"></label></div><?php endforeach;?><div class="col-12"><button class="btn btn-primary">Save material</button></div></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Material</th><th>Category</th><th>Surface</th><th>Maps</th><th>Cost</th><th>State</th></tr></thead><tbody><?php foreach($materials as $m):?><tr><td><b><?=e($m['material_name'])?></b><br><code><?=e($m['material_key'])?></code></td><td><?=e($m['category'])?></td><td><?=e($m['color_hex'])?> · roughness <?=e($m['roughness'])?> · metal <?=e($m['metallic'])?></td><td class="small"><?php foreach(['base_color_map','normal_map','roughness_map','metallic_map','ao_map'] as $field)if($m[$field]):?><span class="me-2"><?=e($field)?></span><?php endif;?></td><td><?=money($m['additional_cost'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="material_catalog_toggle"><input type="hidden" name="material_key" value="<?=e($m['material_key'])?>"><button class="btn btn-sm btn-outline-dark"><?=((int)$m['is_active'])?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?></tbody></table></div><form class="card p-3 mt-4" method="post"><?=csrf_field()?><input type="hidden" name="action" value="color_palette_save"><h2 class="h5">Add a color swatch</h2><div class="row g-2"><div class="col-md-4"><input class="form-control" name="color_name" maxlength="80" placeholder="Color name" required></div><div class="col-md-4"><input class="form-control" name="category" maxlength="32" placeholder="Category" required></div><div class="col-md-2"><input class="form-control" name="color_hex" type="color" value="#7c5b46" required></div><div class="col-md-2"><button class="btn btn-primary">Save color</button></div></div></form><div class="row g-2 mt-2"><?php foreach($colors as $color):?><div class="col-md-4"><div class="card p-2 d-flex flex-row align-items-center gap-2"><span style="display:inline-block;width:28px;height:28px;border-radius:50%;background:<?=e($color['color_hex'])?>"></span><span><?=e($color['color_name'])?> · <?=e($color['category'])?></span><form class="ms-auto" method="post"><?=csrf_field()?><input type="hidden" name="action" value="color_palette_toggle"><input type="hidden" name="color_id" value="<?=$color['color_id']?>"><button class="btn btn-sm btn-outline-dark"><?=((int)$color['is_active'])?'Deactivate':'Activate'?></button></form></div></div><?php endforeach;?></div><?php return true;}
    if($page==='customization-admin')return render_customization_admin_page();
    if($page==='component-admin')return render_component_admin_page();
    if($page==='products-admin'){
      $edit=isset($_GET['edit'])?product((int)$_GET['edit']):null;$ps=db()->query('SELECT p.*,c.category_name,(SELECT image_path FROM product_images WHERE product_id=p.product_id ORDER BY is_primary DESC LIMIT 1) image FROM products p LEFT JOIN categories c USING(category_id) ORDER BY p.created_at DESC')->fetchAll();$cs=db()->query('SELECT * FROM categories ORDER BY category_name')->fetchAll(); ?>
      <div class="d-flex justify-content-between"><h1>Product management</h1><a class="btn btn-outline-dark" href="?page=categories-admin">Categories</a></div><form class="card p-3 my-3" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="product_save"><input type="hidden" name="product_id" value="<?=e($edit['product_id']??'')?>"><div class="row g-2"><div class="col-md-4"><input class="form-control" name="name" placeholder="Product name" required value="<?=e($edit['name']??'')?>"></div><div class="col-md-3"><select class="form-select" name="category_id"><option value="">Uncategorized</option><?php foreach($cs as $c):?><option value="<?=$c['category_id']?>" <?=($edit['category_id']??'')==$c['category_id']?'selected':''?>><?=e($c['category_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" name="base_price" type="number" min="0" step=".01" placeholder="Base price" required value="<?=e($edit['base_price']??'')?>"></div><div class="col-md-3"><select class="form-select" name="availability"><?php foreach(['In Stock','Out of Stock','Archived'] as $a):?><option <?=($edit['availability']??'In Stock')===$a?'selected':''?>><?=$a?></option><?php endforeach;?></select></div><div class="col-12"><textarea class="form-control" name="description" placeholder="Description"><?=e($edit['description']??'')?></textarea></div><?php foreach(['width'=>'Width','height'=>'Height','depth'=>'Depth'] as $d=>$label):?><div class="col-6 col-md-2"><label>Default <?=$label?> cm<input class="form-control" type="number" min="1" step=".1" name="default_<?=$d?>" value="<?=e($edit['default_'.$d.'_cm']??100)?>"></label></div><div class="col-6 col-md-2"><label><?=$label?> rate/cm<input class="form-control" type="number" min="0" step=".01" name="<?=$d?>_rate" value="<?=e($edit[$d.'_rate_per_cm']??0)?>"></label></div><?php endforeach;?><div class="col-md-4"><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="col-md-4"><label><input type="checkbox" name="is_customizable" value="1" <?=($edit['is_customizable']??1)?'checked':''?>> Customizable</label></div><div class="col-12"><button class="btn btn-primary">Save product</button> <a href="?page=products-admin" class="btn btn-light">Clear</a></div></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Availability</th><th></th></tr></thead><tbody><?php foreach($ps as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category_name']??'—')?></td><td><?=money($p['base_price'])?></td><td><?=e($p['availability'])?></td><td><a class="btn btn-sm btn-outline-dark" href="?page=products-admin&edit=<?=$p['product_id']?>">Edit</a> <form class="d-inline" method="post" onsubmit="return confirm('Delete product?')"><?=csrf_field()?><input type="hidden" name="action" value="product_delete"><input type="hidden" name="product_id" value="<?=$p['product_id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php return true;
    }
    if($page==='categories-admin'){$cs=db()->query('SELECT c.*,COUNT(p.product_id) product_count FROM categories c LEFT JOIN products p USING(category_id) GROUP BY c.category_id ORDER BY c.category_name')->fetchAll();?><h1>Category management</h1><form class="card p-3 mb-3" method="post"><?=csrf_field()?><input type="hidden" name="action" value="category_save"><div class="row g-2"><div class="col-md-4"><input class="form-control" name="category_name" placeholder="New category" required></div><div class="col-md-6"><input class="form-control" name="description" placeholder="Description"></div><div class="col-md-2"><button class="btn btn-primary">Create</button></div></div></form><?php foreach($cs as $c):?><article class="card p-3 mb-2"><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="action" value="category_save"><input type="hidden" name="category_id" value="<?=$c['category_id']?>"><div class="col-md-4"><input class="form-control" name="category_name" value="<?=e($c['category_name'])?>"></div><div class="col-md-5"><input class="form-control" name="description" value="<?=e($c['description'])?>"></div><div class="col-md-3"><button class="btn btn-sm btn-primary">Save</button> <span><?=$c['product_count']?> products</span></div></form><?php $q=db()->prepare('SELECT name FROM products WHERE category_id=?');$q->execute([$c['category_id']]);?><small><?=e(implode(', ',$q->fetchAll(PDO::FETCH_COLUMN)))?></small><?php if(!$c['product_count']):?><form method="post" class="mt-2"><?=csrf_field()?><input type="hidden" name="action" value="category_delete"><input type="hidden" name="category_id" value="<?=$c['category_id']?>"><button class="btn btn-sm btn-outline-danger">Delete empty category</button></form><?php endif;?></article><?php endforeach;?><?php return true;}
    if($page==='customization-admin'){$types=db()->query('SELECT * FROM customization_types ORDER BY type_name')->fetchAll();$opts=db()->query('SELECT o.*,t.type_name FROM customization_options o JOIN customization_types t USING(type_id) ORDER BY t.type_name,o.option_name')->fetchAll();$ps=db()->query('SELECT product_id,name FROM products ORDER BY name')->fetchAll();$pid=(int)($_GET['product_id']??($ps[0]['product_id']??0));$q=db()->prepare('SELECT option_id FROM product_customization_options WHERE product_id=?');$q->execute([$pid]);$chosen=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));?><h1>Customization rules</h1><div class="row g-3"><div class="col-lg-4"><form class="card p-3" method="post"><?=csrf_field()?><input type="hidden" name="action" value="custom_type_save"><h2 class="h5">New type</h2><input class="form-control mb-2" name="type_name" placeholder="Material, Color, Finish" required><input class="form-control mb-2" name="description" placeholder="Description"><button class="btn btn-primary">Add type</button></form><form class="card p-3 mt-3" method="post"><?=csrf_field()?><input type="hidden" name="action" value="custom_option_save"><h2 class="h5">New option</h2><select class="form-select mb-2" name="type_id"><?php foreach($types as $t):?><option value="<?=$t['type_id']?>"><?=e($t['type_name'])?></option><?php endforeach;?></select><input class="form-control mb-2" name="option_name" placeholder="Option" required><input class="form-control mb-2" type="number" min="0" step=".01" name="additional_cost" placeholder="Extra price" required><button class="btn btn-primary">Add option</button></form></div><div class="col-lg-8"><h2 class="h5">Options</h2><?php foreach($opts as $o):?><form method="post" class="d-flex justify-content-between p-2 border-bottom"><?=csrf_field()?><input type="hidden" name="action" value="custom_option_toggle"><input type="hidden" name="option_id" value="<?=$o['option_id']?>"><span><?=e($o['type_name'])?>: <?=e($o['option_name'])?> · <?=money($o['additional_cost'])?> · <?=$o['is_active']?'Enabled':'Disabled'?></span><button class="btn btn-sm btn-outline-dark">Toggle</button></form><?php endforeach;?><h2 class="h5 mt-4">Assign options to products</h2><form method="get"><input type="hidden" name="page" value="customization-admin"><select class="form-select" name="product_id" onchange="this.form.submit()"><?php foreach($ps as $p):?><option value="<?=$p['product_id']?>" <?=$p['product_id']===$pid?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form><form method="post" class="card p-3 mt-2"><?=csrf_field()?><input type="hidden" name="action" value="product_options_save"><input type="hidden" name="product_id" value="<?=$pid?>"><?php foreach($opts as $o):?><label class="d-block"><input type="checkbox" name="option_ids[]" value="<?=$o['option_id']?>" <?=in_array((int)$o['option_id'],$chosen,true)?'checked':''?> <?=$o['is_active']?'':'disabled'?>> <?=e($o['type_name'])?> · <?=e($o['option_name'])?> (<?=money($o['additional_cost'])?>)</label><?php endforeach;?><button class="btn btn-primary mt-2">Save assignments</button></form></div></div><?php return true;}
    if($page==='users'){$term=trim((string)($_GET['q']??''));$role=(string)($_GET['role']??'');$sql='SELECT user_id,full_name,email,role,account_status FROM users WHERE (full_name LIKE ? OR email LIKE ?)';$args=['%'.$term.'%','%'.$term.'%'];if(in_array($role,['customer','manufacturer','admin'],true)){$sql.=' AND role=?';$args[]=$role;}$q=db()->prepare($sql.' ORDER BY created_at DESC');$q->execute($args);?><h1>User management</h1><form class="row g-2 mb-3"><input type="hidden" name="page" value="users"><div class="col-md-6"><input class="form-control" name="q" value="<?=e($term)?>" placeholder="Search users"></div><div class="col-md-3"><select class="form-select" name="role"><option value="">All roles</option><?php foreach(['customer','manufacturer','admin'] as $r):?><option value="<?=$r?>" <?=$role===$r?'selected':''?>><?=ucfirst($r)?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-outline-dark">Filter</button></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($q as $u):?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['account_status'])?></td><td><?php if($u['role']!=='admin'):?><form method="post" onsubmit="return confirm('Change this account’s active status?')"><?=csrf_field()?><input type="hidden" name="action" value="user_toggle"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><button class="btn btn-sm btn-outline-dark"><?=$u['account_status']==='active'?'Deactivate':'Activate'?></button></form><?php else:?>Protected<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php return true;}
    if($page==='orders'){$orders=db()->query('SELECT o.*,u.full_name FROM orders o JOIN users u USING(user_id) ORDER BY order_date DESC')->fetchAll();?><div class="d-flex justify-content-between"><h1>Orders</h1><a class="btn btn-outline-dark" href="?page=reports">Reports</a></div><?php foreach($orders as $o):?><div class="card p-3 mb-2"><div class="d-flex justify-content-between flex-wrap"><div><b>#<?=$o['order_id']?> · <?=e($o['full_name'])?></b> · <?=money($o['total_amount'])?> · <?=e($o['status'])?><div class="small"><?=e($o['order_date'])?></div></div><a class="btn btn-sm btn-outline-dark" href="?page=order-admin-detail&id=<?=$o['order_id']?>">Details/history</a></div><form method="post" class="d-flex gap-2 mt-3"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="order_id" value="<?=$o['order_id']?>"><select class="form-select" name="status"><?php foreach(['Confirmed','Processing','Manufacturing','Shipped','Delivered','Cancelled'] as $s):?><option <?=$o['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><input class="form-control" name="notes" placeholder="Status note"><button class="btn btn-primary">Update</button></form></div><?php endforeach;?><?php return true;}
    if($page==='order-admin-detail'){$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT o.*,u.full_name,u.email FROM orders o JOIN users u USING(user_id) WHERE order_id=?');$q->execute([$id]);$o=$q->fetch();if(!$o){echo '<div class="empty">Order not found.</div>';return true;}$items=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$items->execute([$id]);$history=db()->prepare('SELECT h.*,u.full_name FROM order_status_history h LEFT JOIN users u ON u.user_id=h.updated_by WHERE order_id=? ORDER BY updated_at DESC');$history->execute([$id]);?><h1>Order #<?=$id?></h1><p><?=e($o['full_name'])?> · <?=e($o['email'])?> · <?=e($o['status'])?></p><p><?=e($o['delivery_address'])?></p><h2 class="h4">Items</h2><?php foreach($items as $it):?><div class="card p-3 mb-2"><?=e($it['product_name_snapshot'])?> × <?=$it['quantity']?> — <?=money($it['subtotal'])?><?php $cx=db()->prepare('SELECT selected_value,additional_cost FROM order_item_customizations WHERE order_item_id=?');$cx->execute([$it['order_item_id']]);foreach($cx as $x):?><div class="small"><?=e($x['selected_value'])?> · <?=money($x['additional_cost'])?></div><?php endforeach;?><?php $cc=db()->prepare('SELECT component_label,spec_json,additional_cost FROM order_item_component_snapshots WHERE order_item_id=?');$cc->execute([$it['order_item_id']]);foreach($cc as $cs):?><div class="small border-top mt-1 pt-1"><b><?=e($cs['component_label'])?></b> · <?=e(format_component_snapshot($cs['spec_json']))?> · <?=money($cs['additional_cost'])?></div><?php endforeach;?></div><?php endforeach;?><h2 class="h4 mt-4">Status history</h2><?php foreach($history as $h):?><div class="timeline-item"><b><?=e($h['status'])?></b> · <?=e($h['updated_at'])?><div><?=e($h['notes']??'')?></div><small><?=e($h['full_name']??'system')?></small></div><?php endforeach;?><a href="?page=orders">Back to orders</a><?php return true;}
    if($page==='customize')return render_component_product_customizer((int)($_GET['id']??0));
    if($page==='order'){$u=current_user();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM orders WHERE order_id=? AND user_id=?');$q->execute([$id,$u['user_id']]);$o=$q->fetch();if(!$o){http_response_code(404);echo '<div class="empty">Order not found.</div>';return true;}$h=db()->prepare('SELECT * FROM order_status_history WHERE order_id=? ORDER BY updated_at');$h->execute([$id]);$history=$h->fetchAll();$steps=['Pending','Confirmed','Processing','Manufacturing','Shipped','Delivered'];$pos=array_search($o['status'],$steps,true);?><div class="d-flex justify-content-between"><div><span class="eyebrow">Order tracking</span><h1>Order #<?=$id?></h1></div><span class="badge text-bg-primary fs-6"><?=e($o['status'])?></span></div><div class="tracking my-4"><?php foreach($steps as $i=>$stage):?><div class="tracking-step <?=($pos!==false&&$i<=$pos)?'done':''?>"><span><?=($pos!==false&&$i<=$pos)?'✓':$i+1?></span><b><?=$stage?></b><?php foreach($history as $h)if($h['status']===$stage):?><small><?=e($h['updated_at'])?></small><?php if($h['notes']):?><small><?=e($h['notes'])?></small><?php endif;?><?php endif;?></div><?php endforeach;?></div><?php if($o['status']==='Cancelled'):?><div class="alert alert-warning">This order was cancelled.</div><?php endif;?><h2 class="h4">Order items</h2><?php $it=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$it->execute([$id]);foreach($it as $item):?><div class="card p-3 mb-2"><?=e($item['product_name_snapshot'])?> × <?=$item['quantity']?> — <?=money($item['subtotal'])?><?php $cx=db()->prepare('SELECT selected_value FROM order_item_customizations WHERE order_item_id=?');$cx->execute([$item['order_item_id']]);foreach($cx as $x):?><div class="small text-muted"><?=e($x['selected_value'])?></div><?php endforeach;?><?php $cc=db()->prepare('SELECT component_label,spec_json,additional_cost FROM order_item_component_snapshots WHERE order_item_id=?');$cc->execute([$item['order_item_id']]);foreach($cc as $cs):?><div class="small border-top mt-1 pt-1"><b><?=e($cs['component_label'])?></b> · <?=e(format_component_snapshot($cs['spec_json']))?> · <?=money($cs['additional_cost'])?></div><?php endforeach;?></div><?php endforeach;?><p class="fw-semibold">Order total: <?=money($o['total_amount'])?></p><a href="?page=my-orders">All orders</a><?php return true;}
    if($page==='forgot-password'){?><div class="form-shell"><h1>Forgot password</h1><p>Enter your email. If it is registered, a reset link is created.</p><form method="post" class="vstack gap-3"><?=csrf_field()?><input type="hidden" name="action" value="forgot_password"><label>Email<input class="form-control" type="email" name="email" required></label><button class="btn btn-primary">Request reset</button></form></div><?php return true;}
    if($page==='reset-password'){$token=(string)($_GET['token']??'');?><div class="form-shell"><h1>Set a new password</h1><form method="post" class="vstack gap-3"><?=csrf_field()?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="token" value="<?=e($token)?>"><label>New password<input class="form-control" type="password" name="password" minlength="10" required></label><button class="btn btn-primary">Update password</button></form></div><?php return true;}
    if($page==='my-orders'){$u=current_user();$q=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY order_date DESC');$q->execute([$u['user_id']]);$rows=$q->fetchAll();?><h1>My orders</h1><?php if(!$rows):?><div class="empty">No orders yet. <a href="?page=shop">Explore the collection</a></div><?php else:?><div class="table-responsive"><table class="table"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['order_id']?></td><td><?=e($r['order_date'])?></td><td><?=money($r['total_amount'])?></td><td><?=e($r['status'])?></td><td><a class="btn btn-sm btn-outline-dark" href="?page=order&id=<?=$r['order_id']?>">Track and view</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php return true;}
    if($page==='reports'){$sales=db()->query('SELECT DATE_FORMAT(order_date,"%Y-%m") month,COUNT(*) orders,SUM(total_amount) sales FROM orders WHERE status<>"Cancelled" AND order_date>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY DATE_FORMAT(order_date,"%Y-%m") ORDER BY month')->fetchAll();$products=db()->query('SELECT oi.product_name_snapshot name,SUM(oi.quantity) units,SUM(oi.subtotal) revenue FROM order_items oi JOIN orders o USING(order_id) WHERE o.status<>"Cancelled" GROUP BY oi.product_id,oi.product_name_snapshot ORDER BY revenue DESC LIMIT 10')->fetchAll();$cats=db()->query('SELECT c.category_name,COALESCE(SUM(CASE WHEN o.status IS NULL OR o.status<>"Cancelled" THEN oi.subtotal ELSE 0 END),0) revenue FROM categories c LEFT JOIN products p USING(category_id) LEFT JOIN order_items oi USING(product_id) LEFT JOIN orders o USING(order_id) GROUP BY c.category_id ORDER BY revenue DESC')->fetchAll();$stats=db()->query('SELECT (SELECT COUNT(*) FROM orders) orders_total,(SELECT COUNT(*) FROM custom_requests) requests_total,(SELECT COUNT(*) FROM quotations WHERE status IN ("Accepted","Rejected")) decided,(SELECT COUNT(*) FROM quotations WHERE status="Accepted") accepted')->fetch();$max=max(array_map(fn($r)=>(float)$r['sales'],$sales)?:[1]);?><h1>Reports</h1><div class="row g-3 mb-4"><?php foreach(['orders_total'=>'Orders','requests_total'=>'Custom requests','decided'=>'Decided quotations','accepted'=>'Accepted quotations'] as $k=>$label):?><div class="col-6 col-lg-3"><div class="stat-card"><small><?=e($label)?></small><strong><?=$stats[$k]?></strong></div></div><?php endforeach;?></div><?php render_request_quote_summary(); ?><div class="row g-4"><div class="col-lg-7"><div class="card p-4"><h2 class="h4">Monthly sales · last 12 months</h2><?php if(!$sales):?><div class="empty">No sales recorded.</div><?php endif;?><?php foreach($sales as $r):?><div class="report-row"><span><?=e($r['month'])?></span><div class="report-bar"><i style="width:<?=max(2,round((float)$r['sales']/$max*100))?>%"></i></div><b><?=money($r['sales'])?></b><small><?=$r['orders']?> orders</small></div><?php endforeach;?></div></div><div class="col-lg-5"><div class="card p-4"><h2 class="h4">Category sales</h2><?php foreach($cats as $c):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e($c['category_name'])?></span><b><?=money($c['revenue'])?></b></div><?php endforeach;?></div></div><div class="col-12"><div class="card p-4"><h2 class="h4">Product performance</h2><?php table($products,['name'=>'Product','units'=>'Units sold','revenue'=>'Sales']);?></div></div></div><p class="small text-muted mt-3">Live database statistics; cancelled orders are excluded from sales.</p><?php return true;}
    if($page==='quotations'&&current_user()['role']==='admin'){$rows=db()->query('SELECT q.*,cr.title,cr.furniture_type FROM quotations q JOIN custom_requests cr USING(request_id) ORDER BY q.created_at DESC')->fetchAll();$requests=db()->query('SELECT request_id,title,furniture_type FROM custom_requests ORDER BY created_at DESC')->fetchAll();?><h1>Quotations</h1><form class="card p-3 mb-3" method="post"><?=csrf_field()?><input type="hidden" name="action" value="quotation_admin_save"><div class="row g-2"><div class="col-md-3"><select class="form-select" name="request_id"><?php foreach($requests as $r):?><option value="<?=$r['request_id']?>">#<?=$r['request_id']?> · <?=e($r['title']?:$r['furniture_type'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" name="price" type="number" min=".01" step=".01" placeholder="Price" required></div><div class="col-md-2"><input class="form-control" name="estimated_time" placeholder="Lead time" required></div><div class="col-md-2"><input class="form-control" name="valid_until" type="date"></div><div class="col-md-2"><input class="form-control" name="notes" placeholder="Notes"></div><div class="col-md-1"><button class="btn btn-primary">Save</button></div></div></form><?php foreach($rows as $r):?><article class="card p-3 mb-3"><b>#<?=$r['quotation_id']?> · Request #<?=$r['request_id']?> · <?=e($r['status'])?></b><p><?=e($r['title']?:$r['furniture_type'])?> · <?=money($r['price'])?> · <?=e($r['estimated_time'])?></p><?php if($r['status']==='Draft'):?><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="action" value="quotation_admin_save"><input type="hidden" name="quotation_id" value="<?=$r['quotation_id']?>"><div class="col-md-2"><input class="form-control" name="price" type="number" min=".01" step=".01" value="<?=$r['price']?>"></div><div class="col-md-3"><input class="form-control" name="estimated_time" value="<?=e($r['estimated_time'])?>"></div><div class="col-md-3"><input class="form-control" name="valid_until" type="date" value="<?=e($r['valid_until']??'')?>"></div><div class="col-md-3"><input class="form-control" name="notes" value="<?=e($r['notes']??'')?>"></div><div class="col-12 d-flex gap-2"><button class="btn btn-outline-dark">Save draft</button></form><form method="post" onsubmit="return confirm('Send this quotation to the customer?')"><?=csrf_field()?><input type="hidden" name="action" value="quotation_admin_send"><input type="hidden" name="quotation_id" value="<?=$r['quotation_id']?>"><button class="btn btn-primary">Send quotation</button></form></div><?php else:?><p><?=e($r['notes']??'')?></p><?php endif;?></article><?php endforeach;?><?php return true;}
    return false;
}

function render_component_product_customizer(int $productId): bool {
    $p=product($productId);if(!$p||!$p['is_customizable']){echo '<div class="empty">This product cannot be customized.</div>';return true;}
    $components=component_definitions($productId);if(!$components){echo '<div class="alert alert-warning"><h1 class="h4">Component model unavailable</h1><p>This product has no component-level model configured. Its basic options remain available from the product page. This page will not imply that its parts can be changed.</p><a class="btn btn-outline-dark" href="?page=product&id='.$productId.'">Return to product</a></div>';return true;}
    $q=db()->prepare('SELECT o.*,t.type_name FROM product_customization_options po JOIN customization_options o USING(option_id) JOIN customization_types t USING(type_id) WHERE po.product_id=? AND o.is_active=1 ORDER BY t.type_name,o.option_name');$q->execute([$productId]);$options=$q->fetchAll();$groups=[];foreach($options as $o)$groups[$o['type_name']][]=$o;
    $q=db()->prepare('SELECT * FROM product_dimension_rules WHERE product_id=? ORDER BY FIELD(dimension_name,"width","height","depth")');$q->execute([$productId]);$rules=$q->fetchAll();$ranges=[];foreach($rules as $r)if($r['pricing_mode']==='ranges'){$x=db()->prepare('SELECT min_cm,max_cm,additional_cost FROM product_dimension_price_ranges WHERE product_id=? AND dimension_name=? ORDER BY min_cm');$x->execute([$productId,$r['dimension_name']]);$ranges[$r['dimension_name']]=$x->fetchAll();}
    $cfg=json_encode($components,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE);$palette=json_encode(component_color_palette(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE);$dimensionData=json_encode(['rules'=>$rules,'ranges'=>$ranges,'base_price'=>(float)$p['base_price']],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE);$kind=$p['customization_preview_kind']??'generic';$models=[1=>'assets/models/arden_sofa_innerscene.glb',2=>'assets/models/milo_coffee_table_cove_122.glb',3=>'assets/models/haven_spindle_frame_bed.glb',4=>'assets/models/linden_wingfold_butterfly_table_cc0.glb',5=>'assets/models/studio_desk_innerscene.glb',8=>'assets/models/modular_wardrobe.glb'];$modelPath=$models[$productId]??'';$modelFile=$modelPath?dirname(__DIR__).'/'.$modelPath:'';$modelUrl=$modelPath?($modelPath.'?v='.(is_file($modelFile)?filemtime($modelFile):'1')):'';$fallbackImage=furniflex_product_image($p);
    $capabilityCopy=$productId===2?'Select the tabletop, legs, or lower shelf in the GLB. Supported dimensions, materials, colors, and finishes update those separate groups. Leg count and assembly positions stay fixed; the lower shelf can be removed.':'Local GLB mesh groups are independently selectable. Supported changes update the selected component geometry and PBR surface.';
    ?><div class="row g-4 customizer component-customizer" data-product-id="<?=$productId?>" data-model-url="<?=e($modelUrl)?>" data-preview-kind="<?=e($kind)?>"><div class="col-lg-7"><div class="customizer-preview three-preview"><div class="preview-stage three-stage"><?php if($fallbackImage):?><img class="preview-fallback configurator-fallback" src="<?=e($fallbackImage)?>" alt="<?=e($p['name'])?>" loading="eager" decoding="async" fetchpriority="high"><?php else:?><div class="preview-fallback preview-unavailable configurator-fallback" role="img" aria-label="Product image unavailable for <?=e($p['name'])?>"><strong><?=e($p['name'])?></strong><span>3D model loading…</span></div><?php endif;?><canvas id="component-canvas" aria-label="Interactive 3D furniture configurator"></canvas><div class="three-status" id="three-status">Loading the local component model…</div><div class="three-controls"><button type="button" class="btn btn-sm btn-light" id="rotate-model">Auto rotate</button><button type="button" class="btn btn-sm btn-light" id="reset-camera">Reset View</button></div></div><div class="small text-muted mt-2">Drag to rotate · scroll to zoom · click a modeled part to select it</div></div><h1 class="mt-3"><?=e($p['name'])?></h1><p><?=e($p['description'])?></p><p id="preview-status" class="small text-muted"><?=e($capabilityCopy)?></p></div>
    <div class="col-lg-5"><form method="post" class="card p-3 p-md-4 customizer-form" id="component-form"><?=csrf_field()?><input type="hidden" name="action" value="customized_add_cart"><input type="hidden" name="product_id" value="<?=$productId?>"><input type="hidden" name="component_specs" id="component-specs"><h2 class="h4">Customize components</h2><div class="small text-muted">Base price <span id="base-price" data-base="<?=$p['base_price']?>"><?=money($p['base_price'])?></span></div>
    <?php if($rules):?><fieldset class="overall-dimensions mt-3"><legend class="h5">Overall Dimensions</legend><p class="small text-muted mb-2">These dimensions are saved with your configuration and priced by the displayed size rules. Change a dimension to resize the assembled preview.</p><div class="row g-2"><?php foreach($rules as $rule):$d=$rule['dimension_name'];$label=['width'=>'Overall Width','depth'=>'Overall Length / Depth','height'=>'Overall Height'][$d]??ucfirst($d);?><div class="col-12 col-md-6"><label class="form-label" for="overall-<?=$d?>"><?=$label?> (cm)</label><div class="input-group"><button class="btn btn-outline-secondary" type="button" data-dimension-step="-1" data-target="overall-<?=$d?>" aria-label="Decrease <?=$label?>">−</button><input id="overall-<?=$d?>" class="form-control overall-dimension-input" type="number" name="<?=$d?>" min="<?=e($rule['min_cm'])?>" max="<?=e($rule['max_cm'])?>" step="<?=e($rule['step_cm'])?>" value="<?=e($rule['default_cm'])?>" data-default="<?=e($rule['default_cm'])?>" required><button class="btn btn-outline-secondary" type="button" data-dimension-step="1" data-target="overall-<?=$d?>" aria-label="Increase <?=$label?>">+</button></div><small class="text-muted d-block mt-1">Default <?=number_format((float)$rule['default_cm'],1)?> cm · range <?=number_format((float)$rule['min_cm'],1)?>–<?=number_format((float)$rule['max_cm'],1)?> cm</small></div><?php endforeach;?></div><button class="btn btn-outline-secondary btn-sm mt-2" type="button" id="reset-dimensions">Reset Dimensions</button></fieldset><?php endif;?>
    <?php if($groups):?><details class="mt-3"><summary class="fw-semibold">Overall surface choices</summary><p class="small text-muted">These apply as fallbacks to components without a component-specific surface choice. Component controls below override them.</p><?php foreach($groups as $type=>$group):?><fieldset class="option-group mt-3"><legend><?=e($type)?></legend><div class="option-cards <?=(strtolower($type)==='color'?'swatches':'')?>"><?php foreach($group as $o):?><label class="option-card <?=strtolower($type)==='color'?'swatch-card':''?>"><input class="option-input" type="radio" name="options[<?=e($type)?>]" value="<?=$o['option_id']?>" data-cost="<?=$o['additional_cost']?>" data-color="<?=e($o['preview_color']??'')?>" data-image="<?=e($o['preview_image_path']??'')?>" data-layer="<?=e($o['preview_layer_key'])?>"><?php if(strtolower($type)==='color'):?><span class="swatch" style="--swatch:<?=e($o['preview_color']?:'#ddd')?>"></span><?php endif;?><span><?=e($o['option_name'])?></span><small><?=money($o['additional_cost'])?></small></label><?php endforeach;?></div></fieldset><?php endforeach;?></details><?php endif;?>
    <h3 class="h5 mt-4">Select a component</h3><section class="color-lab" aria-label="Selected component color editor"><div class="d-flex justify-content-between align-items-start gap-2"><div><h4 class="h6 mb-1">Color palette <span id="color-target-label">(select a component)</span></h4><p class="small text-muted mb-2">Color applies only to the selected component. You can enter any HEX value.</p></div><button type="button" class="btn btn-sm btn-outline-dark" id="favorite-color">☆ Save favorite</button></div><div class="row g-2 align-items-end"><div class="col-6"><label>Category<select class="form-select" id="color-category"><option value="all">All colors</option><?php foreach(array_unique(array_column(component_color_palette(),'category')) as $category):?><option><?=e($category)?></option><?php endforeach;?></select></label></div><div class="col-6"><label>Custom color<input class="form-control form-control-color" type="color" id="custom-color-picker" value="#cabaa3"></label></div><div class="col-8"><label>HEX<input class="form-control" id="custom-color-hex" value="#CABAA3" maxlength="7" pattern="^#[0-9a-fA-F]{6}$"></label></div><div class="col-4"><output id="color-rgb" class="small text-muted">RGB 202, 186, 163</output></div></div><div id="palette-swatches" class="palette-swatches mt-2"></div><div class="small mt-2">Recent: <span id="recent-colors"></span> · Favorites: <span id="favorite-colors"></span></div></section>
    <div class="component-list" id="component-list"><?php foreach($components as $c):$shapes=$c['allowed_shapes'];$materialChoices=array_values(array_filter($c['options'],fn($o)=>$o['option_type']==='material'));?><article class="component-card" data-component-id="<?=$c['component_id']?>"><button type="button" class="component-select" data-select-component="<?=$c['component_id']?>"><span><?=e($c['display_name'])?></span><small>Component #<?=$c['component_id']?></small></button><div class="row g-2 mt-1"><div class="col-6"><label>Shape<select class="form-select component-field" data-field="shape" data-component-id="<?=$c['component_id']?>"><?php foreach($shapes as $sh):?><option value="<?=e($sh)?>" <?=$c['default_shape']===$sh?'selected':''?>><?=ucfirst(str_replace('_',' ',$sh))?></option><?php endforeach;?></select></label></div><div class="col-6"><label>Quantity<input class="form-control component-field" type="number" data-field="quantity" data-component-id="<?=$c['component_id']?>" min="<?=$c['min_quantity']?>" max="<?=$c['max_quantity']?>" step="1" value="<?=$c['default_quantity']?>"></label></div><?php foreach(['width'=>'Width','depth'=>'Depth','height'=>'Height'] as $axis=>$label):$col='default_'.$axis.'_cm';?><div class="col-4"><label><?=$label?> cm<input class="form-control component-field" type="number" step="<?=((int)round(100*($c[$col]-$c['min_'.$axis.'_cm'])))%10===0?'.1':'.01'?>" data-field="<?=$axis?>_cm" data-component-id="<?=$c['component_id']?>" min="<?=$c['min_'.$axis.'_cm']?>" max="<?=$c['max_'.$axis.'_cm']?>" value="<?=$c[$col]?>"></label></div><?php endforeach;?><div class="col-12"><div class="small fw-semibold">Position · centimeters</div></div><?php foreach(['x'=>'X','y'=>'Y','z'=>'Z'] as $axis=>$label):?><div class="col-4"><label><?=$label?><input class="form-control component-field" type="number" step=".5" data-field="position_<?=$axis?>" data-component-id="<?=$c['component_id']?>" min="<?=$c['min_'.$axis.'_cm']?>" max="<?=$c['max_'.$axis.'_cm']?>" value="<?=$c['default_'.$axis.'_cm']?>"></label></div><?php endforeach;?>
    <?php foreach(['material'=>'Material','color'=>'Color','finish'=>'Finish'] as $type=>$label):$choices=array_values(array_filter($c['options'],fn($o)=>$o['option_type']===$type));if(!$choices)continue;$defaultKey=$type==='color'?'default_color_hex':($type==='material'?'default_material':'default_finish');?><div class="col-12"><label><?=$label?><select class="form-select component-field component-option" data-field="option_<?=$type?>" data-component-id="<?=$c['component_id']?>"><option value="0">Default · <?=e($c[$defaultKey])?></option><?php foreach($choices as $choice):?><option value="<?=$choice['component_option_id']?>" data-cost="<?=$choice['additional_cost']?>" data-color="<?=e($choice['color_hex'])?>" data-texture="<?=e($choice['texture_key'])?>"><?=e($choice['option_name'])?> (+<?=money($choice['additional_cost'])?> per part)</option><?php endforeach;?></select></label></div><?php endforeach;?><input type="hidden" class="component-field" data-field="custom_color" data-component-id="<?=$c['component_id']?>" value=""><div class="col-12"><details class="material-library"><summary>Browse material cards · <?=count($materialChoices)?> available</summary><div class="row g-2 mt-2"><div class="col-7"><input class="form-control material-search" type="search" placeholder="Search materials"></div><div class="col-5"><select class="form-select material-category"><option value="all">All categories</option><?php foreach(array_unique(array_column($materialChoices,'material_category')) as $category):?><option value="<?=e($category)?>"><?=e(ucfirst((string)$category))?></option><?php endforeach;?></select></div></div><div class="material-cards mt-2"><?php foreach($materialChoices as $mat):?><button type="button" class="material-card" data-option-id="<?=$mat['component_option_id']?>" data-name="<?=e(strtolower($mat['option_name']))?>" data-category="<?=e($mat['material_category']??'')?>"><img loading="lazy" src="<?=e($mat['preview_image']?:furniflex_fallback_image())?>" alt=""><span><?=e($mat['option_name'])?></span><small>+<?=money($mat['additional_cost'])?> / part</small></button><?php endforeach;?></div></details></div></div></article><?php endforeach;?></div>
    <div class="price-breakdown mt-3"><h3 class="h6">Live price breakdown</h3><div class="breakdown-row"><span>Base price</span><b><?=money($p['base_price'])?></b></div><div id="dimension-breakdown"></div><div id="option-breakdown"></div><div id="component-breakdown"></div><div class="price-estimate mt-2"><span>Estimated total</span><strong id="estimated-total"><?=money($p['base_price'])?></strong></div><button class="btn btn-outline-secondary btn-sm mt-3 w-100" type="button" id="reset-config">Reset to Default</button><dialog id="reset-confirm" class="reset-confirm"><h2 class="h5">Reset configuration?</h2><p>Reset all customizations to the original product settings?</p><div class="d-flex justify-content-end gap-2"><button class="btn btn-light" type="button" id="cancel-reset">Cancel</button><button class="btn btn-primary" type="button" id="confirm-reset">Reset</button></div></dialog></div><p class="small text-muted mt-2">The server rebuilds and validates every component and price before adding to your cart.</p><div class="d-flex gap-2 mt-3"><input class="form-control" aria-label="Quantity" style="max-width:100px" type="number" name="quantity" min="1" max="99" value="1"><button class="btn btn-primary" type="submit" id="add-configured-item" disabled>Add configured piece</button></div></form></div></div>
    <script type="application/json" id="component-config-data"><?=$cfg?></script><script type="application/json" id="component-color-data"><?=$palette?></script><script type="application/json" id="overall-dimension-data"><?=$dimensionData?></script><script>function showConfiguratorFallback(message,error){if(error)console.error('FurniFlex configurator runtime error',error);const s=document.getElementById('three-status'),stage=document.querySelector('.three-stage'),submit=document.getElementById('add-configured-item');stage?.classList.remove('model-ready');stage?.classList.add('model-error');if(s){s.textContent=message;s.classList.add('is-error')}if(submit)submit.disabled=true}window.addEventListener('error',e=>showConfiguratorFallback('The furniture preview failed. The product image is shown; please reload.',e.error||e.message));window.addEventListener('unhandledrejection',e=>showConfiguratorFallback('The furniture preview failed. The product image is shown; please reload.',e.reason));</script><script type="module" src="assets/js/component-configurator.js?v=assembly-dimensions-1"></script><?php return true;
}

function render_product_customizer(int $productId): bool {
    $p=product($productId);if(!$p||!$p['is_customizable']){echo '<div class="empty">This product cannot be customized.</div>';return true;}
    $q=db()->prepare('SELECT o.*,t.type_name FROM product_customization_options po JOIN customization_options o USING(option_id) JOIN customization_types t USING(type_id) WHERE po.product_id=? AND o.is_active=1 ORDER BY t.type_name,o.option_name');$q->execute([$productId]);$options=$q->fetchAll();$groups=[];foreach($options as $o)$groups[$o['type_name']][]=$o;
    $q=db()->prepare('SELECT * FROM product_dimension_rules WHERE product_id=? ORDER BY FIELD(dimension_name,"width","height","depth")');$q->execute([$productId]);$rules=$q->fetchAll();$ranges=[];foreach($rules as $r)if($r['pricing_mode']==='ranges'){$x=db()->prepare('SELECT min_cm,max_cm,additional_cost FROM product_dimension_price_ranges WHERE product_id=? AND dimension_name=? ORDER BY min_cm');$x->execute([$productId,$r['dimension_name']]);$ranges[$r['dimension_name']]=$x->fetchAll();}
    $kind=$p['customization_preview_kind']??'generic';$shape=['sofa'=>'<path class="preview-material-target" d="M105 160h290v105H105z"/><path class="preview-material-target" d="M80 168q0-28 28-28h22v126h-50zm312 0q0-28-28-28h-22v126h50z"/><path d="M120 265v40m260-40v40" stroke="#654832" stroke-width="14" stroke-linecap="round"/>', 'coffee_table'=>'<path class="preview-material-target" d="M100 115h300q20 0 20 20v34H80v-34q0-20 20-20z"/><path d="M115 169v110m270-110v110" stroke="#74523d" stroke-width="16" stroke-linecap="round"/>','bed'=>'<path class="preview-material-target" d="M90 165h320v105H90z"/><path d="M90 165v-50h65v50m-55 105v32m270-32v32" stroke="#76543d" stroke-width="14" stroke-linecap="round"/><path d="M105 150h90v35h-90z" fill="#eee8dc"/>','dining_table'=>'<path class="preview-material-target" d="M70 120h360v45H70z"/><path d="M105 165v135m290-135v135" stroke="#74523d" stroke-width="18" stroke-linecap="round"/>'][$kind]??'';
    ?><div class="row g-4 customizer" data-preview-kind="<?=e($kind)?>"><div class="col-lg-5"><div class="customizer-preview" id="customizer-preview"><div class="preview-stage"><img class="preview-fallback" src="<?=e(furniflex_fallback_image())?>" alt="<?=e($p['name'])?>" loading="eager" decoding="async"><img class="preview-layer" alt="" hidden><div class="preview-material" hidden></div></div></div><p class="small text-muted mt-2" id="preview-status">Illustrative preview. Color choices tint the diagram; the preview is not a photorealistic rendering.</p><h1 class="mt-3"><?=e($p['name'])?></h1><p><?=e($p['description'])?></p><div class="small" id="dimension-summary"></div></div>
    <div class="col-lg-7"><form method="post" class="card p-4 customizer-form"><?=csrf_field()?><input type="hidden" name="action" value="customized_add_cart"><input type="hidden" name="product_id" value="<?=$productId?>"><h2 class="h4">Build your piece</h2><div class="small text-muted">Base price <span id="base-price" data-base="<?=$p['base_price']?>"><?=money($p['base_price'])?></span></div><div class="row g-3 mt-1">
    <?php foreach($rules as $r):$d=$r['dimension_name'];$label=ucfirst($d);?><div class="col-sm-4"><label class="form-label"><?=$label?> (cm)<input class="form-control dimension-input" type="number" name="<?=$d?>" min="<?=$r['min_cm']?>" max="<?=$r['max_cm']?>" step="<?=$r['step_cm']?>" value="<?=$r['default_cm']?>" data-key="<?=$d?>" data-min="<?=$r['min_cm']?>" data-max="<?=$r['max_cm']?>" data-step="<?=$r['step_cm']?>" data-default="<?=$r['default_cm']?>" data-mode="<?=$r['pricing_mode']?>" data-amount="<?=$r['price_amount']?>" <?php if(isset($ranges[$d])):?>data-ranges="<?=e(json_encode($ranges[$d]))?>"<?php endif;?> required></label><small class="text-muted"><?=$r['min_cm']?>–<?=$r['max_cm']?> cm</small></div><?php endforeach;?>
    <?php foreach($groups as $type=>$group):$swatch=strtolower($type)==='color';?><div class="col-12"><fieldset class="option-group"><legend><?=e($type)?></legend><?php if($swatch):?><div class="option-cards swatches"><?php endif;?><?php foreach($group as $i=>$o):if($swatch):?><label class="option-card swatch-card"><input class="option-input" type="radio" name="options[<?=e($type)?>]" value="<?=$o['option_id']?>" data-cost="<?=$o['additional_cost']?>" data-color="<?=e($o['preview_color']??'')?>" data-image="<?=e($o['preview_image_path']??'')?>" data-layer="<?=e($o['preview_layer_key'])?>"><span class="swatch" style="--swatch:<?=e($o['preview_color']?:'#ddd')?>"></span><span><?=e($o['option_name'])?></span><small><?=money($o['additional_cost'])?></small></label><?php else:?><label class="option-card"><input class="option-input" type="radio" name="options[<?=e($type)?>]" value="<?=$o['option_id']?>" data-cost="<?=$o['additional_cost']?>" data-color="<?=e($o['preview_color']??'')?>" data-image="<?=e($o['preview_image_path']??'')?>" data-layer="<?=e($o['preview_layer_key'])?>"><span><b><?=e($o['option_name'])?></b><small><?=money($o['additional_cost'])?> extra</small></span></label><?php endif;?><?php endforeach;?><?php if($swatch):?></div><?php endif;?></fieldset></div><?php endforeach;?></div>
    <div class="price-breakdown mt-4"><h3 class="h6">Price breakdown</h3><div class="breakdown-row"><span>Base price</span><b><?=money($p['base_price'])?></b></div><div id="dimension-breakdown"></div><div id="option-breakdown"></div><div class="price-estimate mt-2"><span>Estimated total</span><strong id="estimated-total"><?=money($p['base_price'])?></strong></div></div><p class="small text-muted mt-2">Final price is recalculated and checked on the server before adding to cart.</p><div class="d-flex gap-2 mt-3"><input class="form-control" aria-label="Quantity" style="max-width:100px" type="number" name="quantity" min="1" max="99" value="1"><button class="btn btn-primary" type="submit">Add to cart</button><button class="btn btn-outline-secondary" type="reset">Reset</button></div></form></div></div><?php return true;
}

function render_component_definition_form(array $c,int $productId): void {
    $id=(int)($c['component_id']??0);$aq=db()->prepare('SELECT component_key,display_name FROM product_components WHERE product_id=? AND component_id<>? ORDER BY component_id');$aq->execute([$productId,$id]);$anchorChoices=$aq->fetchAll();$shapes=$c['allowed_shapes']??['rectangular'];$shapePrices=$c['shape_prices']??['rectangular'=>0];
    ?><form method="post" class="card p-3 component-admin-form"><?=csrf_field()?><input type="hidden" name="action" value="component_definition_save"><input type="hidden" name="component_id" value="<?=$id?>"><input type="hidden" name="product_id" value="<?=$productId?>"><div class="row g-2"><div class="col-md-3"><label>Component key<input class="form-control" name="component_key" value="<?=e($c['component_key']??'')?>" placeholder="e.g. wardrobe_door" required></label></div><div class="col-md-3"><label>Display name<input class="form-control" name="display_name" value="<?=e($c['display_name']??'')?>" required></label></div><div class="col-md-3"><label>Geometry<select class="form-select" name="geometry_type"><?php foreach(['box','panel','cushion','leg','top','door','drawer','shelf','handle'] as $type):?><option value="<?=$type?>" <?=($c['geometry_type']??'box')===$type?'selected':''?>><?=$type?></option><?php endforeach;?></select></label></div><div class="col-md-3"><label>Quantity layout<select class="form-select" name="layout_axis"><?php foreach(['none','x','y','z','corners','shelves','columns','spread_z'] as $a):?><option value="<?=$a?>" <?=($c['layout_axis']??'none')===$a?'selected':''?>><?=$a?></option><?php endforeach;?></select></label></div><div class="col-md-3"><label>Anchored to (optional)<select class="form-select" name="anchor_component_key"><option value="">No host</option><?php foreach($anchorChoices as $choice):?><option value="<?=e($choice['component_key'])?>" <?=($c['anchor_component_key']??'')===$choice['component_key']?'selected':''?>><?=e($choice['display_name'])?></option><?php endforeach;?></select></label></div><div class="col-md-3"><label>Default shape<input class="form-control" name="default_shape" value="<?=e($c['default_shape']??'rectangular')?>" required></label></div><div class="col-md-5"><label>Supported shape keys<input class="form-control" name="allowed_shapes" value="<?=e(implode(',',$shapes))?>" placeholder="rectangular,rounded,arched" required></label></div><div class="col-md-4"><label>Shape surcharges (JSON)<input class="form-control" name="shape_prices_json" value="<?=e(json_encode($shapePrices,JSON_UNESCAPED_SLASHES))?>"></label></div>
    <?php foreach(['width'=>'Width','depth'=>'Depth','height'=>'Height'] as $axis=>$label):?><div class="col-12 mt-2 fw-semibold"><?=$label?> cm · defaults, limits and surcharge/cm</div><div class="col-4"><label>Default<input class="form-control" type="number" step=".1" name="default_<?=$axis?>" value="<?=e($c['default_'.$axis.'_cm']??50)?>"></label></div><div class="col-4"><label>Minimum<input class="form-control" type="number" step=".1" name="min_<?=$axis?>" value="<?=e($c['min_'.$axis.'_cm']??1)?>"></label></div><div class="col-4"><label>Maximum<input class="form-control" type="number" step=".1" name="max_<?=$axis?>" value="<?=e($c['max_'.$axis.'_cm']??200)?>"></label></div><div class="col-12"><label>Surcharge per cm difference<input class="form-control" type="number" min="0" step=".01" name="<?=$axis?>_rate" value="<?=e($c[$axis.'_rate']??0)?>"></label></div><?php endforeach;?>
    <div class="col-12 mt-2 fw-semibold">Quantity · added-part price</div><?php foreach(['default_quantity'=>'Default quantity','min_quantity'=>'Minimum','max_quantity'=>'Maximum','unit_price'=>'Price for each part above default'] as $field=>$label):?><div class="col-6 col-md-3"><label><?=$label?><input class="form-control" type="number" min="0" step="1" name="<?=$field?>" value="<?=e($c[$field]??($field==='default_quantity'?1:($field==='max_quantity'?10:0)))?>"></label></div><?php endforeach;?>
    <?php foreach(['x'=>'X','y'=>'Y','z'=>'Z'] as $axis=>$label):?><div class="col-12 mt-2 fw-semibold"><?=$label?> position · cm</div><?php foreach(['default'=>'Default','min'=>'Minimum','max'=>'Maximum'] as $part=>$caption):$field=$part.'_'.$axis.'_cm';$handler=$part.'_'.$axis;?><div class="col-4"><label><?=$caption?><input class="form-control" type="number" step=".5" name="<?=$handler?>" value="<?=e($c[$field]??($part==='default'?0:($part==='min'?-200:200)))?>"></label></div><?php endforeach;?><?php endforeach;?>
    <div class="col-12 mt-3"><button class="btn btn-primary"><?=$id?'Save component definition':'Add component definition'?></button></div></div></form><?php
}

function render_component_admin_page(): bool {
    $products=db()->query('SELECT product_id,name FROM products ORDER BY name')->fetchAll();$pid=(int)($_GET['product_id']??($products[0]['product_id']??0));$q=db()->prepare('SELECT * FROM product_components WHERE product_id=? ORDER BY component_id');$q->execute([$pid]);$components=$q->fetchAll();
    ?><h1>3D component models</h1><p class="text-secondary">Edit each parametric part’s shape choices, dimensions, quantity limits, position ranges, and server-priced modifications.</p><form method="get" class="mb-3"><input type="hidden" name="page" value="component-admin"><label>Product<select class="form-select" name="product_id" onchange="this.form.submit()"><?php foreach($products as $p):?><option value="<?=$p['product_id']?>" <?=$p['product_id']===$pid?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label></form>
    <h2 class="h4">Add a component definition</h2><?php render_component_definition_form([], $pid);?><h2 class="h4 mt-4">Current components</h2><?php if(!$components):?><div class="alert alert-warning">This product has no editable parametric components.</div><?php endif;?><?php foreach($components as $c):$c['allowed_shapes']=json_decode($c['allowed_shapes_json'],true)?:[];$c['shape_prices']=json_decode($c['shape_prices_json'],true)?:[];?><details class="card mb-3"><summary class="card-header d-flex justify-content-between"><span><?=e($c['display_name'])?> · <?=e($c['geometry_type'])?> · <?=$c['is_active']?'active':'disabled'?></span><span class="small">Key: <?=e($c['component_key'])?></span></summary><div class="card-body"><?php render_component_definition_form($c,$pid);?><form method="post" class="mt-2"><?=csrf_field()?><input type="hidden" name="action" value="component_toggle"><input type="hidden" name="product_id" value="<?=$pid?>"><input type="hidden" name="component_id" value="<?=$c['component_id']?>"><button class="btn btn-sm btn-outline-secondary"><?=$c['is_active']?'Disable this part':'Enable this part'?></button></form><h3 class="h6 mt-3">Materials, colors and finishes available for this part</h3><?php $oq=db()->prepare('SELECT * FROM product_component_options WHERE component_id=? ORDER BY option_type,option_name');$oq->execute([$c['component_id']]);foreach($oq as $o):?><div class="d-flex justify-content-between border-bottom py-1"><span><?=e($o['option_type'])?>: <?=e($o['option_name'])?> · <?=e($o['texture_key'])?> · <?=money($o['additional_cost'])?></span><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="component_option_toggle"><input type="hidden" name="product_id" value="<?=$pid?>"><input type="hidden" name="component_id" value="<?=$c['component_id']?>"><input type="hidden" name="component_option_id" value="<?=$o['component_option_id']?>"><button class="btn btn-sm btn-link"><?=$o['is_active']?'Disable':'Enable'?></button></form></div><?php endforeach;?><form method="post" class="row g-2 mt-2"><?=csrf_field()?><input type="hidden" name="action" value="component_option_save"><input type="hidden" name="product_id" value="<?=$pid?>"><input type="hidden" name="component_id" value="<?=$c['component_id']?>"><div class="col-6 col-md-2"><select class="form-select" name="option_type"><option>material</option><option>color</option><option>finish</option></select></div><div class="col-6 col-md-3"><input class="form-control" name="option_name" placeholder="Oak / Charcoal / Matte" required></div><div class="col-6 col-md-2"><input class="form-control form-control-color" type="color" name="color_hex" value="#a98568"></div><div class="col-6 col-md-2"><select class="form-select" name="texture_key"><?php foreach(['solid','oak','walnut','fabric','velvet','leather','metal','matte','oil','gloss'] as $t):?><option><?=$t?></option><?php endforeach;?></select></div><div class="col-6 col-md-2"><input class="form-control" type="number" min="0" step=".01" name="additional_cost" placeholder="Price / part" required></div><div class="col-6 col-md-1"><button class="btn btn-outline-dark">Add</button></div></form></div></details><?php endforeach;?><p class="small text-muted">Textures are generated locally in the browser. Component values and all associated pricing are validated by PHP.</p><?php return true;
}

