    $rq=db()->prepare('SELECT * FROM product_dimension_rules WHERE product_id=?');$rq->execute([$pid]);$dimensionRules=[];foreach($rq->fetchAll() as $r)$dimensionRules[$r['dimension_name']]=$r;$pq=db()->prepare('SELECT customization_preview_kind FROM products WHERE product_id=?');$pq->execute([$pid]);$previewKind=$pq->fetchColumn()?:'generic';
