    <div class="row g-4"><section class="col-lg-4"><form class="card p-3 mb-3" method="post"><?=csrf_field()?><input type="hidden" name="action" value="custom_type_save"><h2 class="h5">Add a customization type</h2><input class="form-control mb-2" name="type_name" placeholder="Material, Color, Finish" required><input class="form-control mb-2" name="description" placeholder="Description"><button class="btn btn-primary">Create type</button></form>
    <h2 class="h5">Edit types</h2><?php foreach($types as $t):?><form class="card p-2 mb-2" method="post"><?=csrf_field()?><input type="hidden" name="action" value="custom_type_save"><input type="hidden" name="type_id" value="<?=$t['type_id']?>"><input class="form-control mb-1" name="type_name" value="<?=e($t['type_name'])?>"><input class="form-control mb-1" name="description" value="<?=e($t['description']??'')?>"><button class="btn btn-sm btn-outline-dark">Save type</button></form><?php endforeach;?></section>
    <section class="col-lg-8"><form class="card p-3 mb-3" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="custom_option_save"><h2 class="h5">Add an option</h2><div class="row g-2"><div class="col-md-3"><select class="form-select" name="type_id"><?php foreach($types as $t):?><option value="<?=$t['type_id']?>"><?=e($t['type_name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><input class="form-control" name="option_name" placeholder="Option name" required></div><div class="col-md-3"><input class="form-control" type="number" min="0" step=".01" name="additional_cost" placeholder="Extra price" required></div><div class="col-md-2"><button class="btn btn-primary">Add</button></div><div class="col-md-4"><label>Preview color<input class="form-control form-control-color" type="color" name="preview_color" value="#c9aa85"></label></div><div class="col-md-4"><label>Preview layer<select class="form-select" name="preview_layer_key"><option>main</option><option>overlay</option><option>material</option><option>component</option></select></label></div><div class="col-md-4"><label>Preview image<input class="form-control" type="file" name="preview_image" accept="image/png,image/webp,image/jpeg"></label></div></div></form>
    <h2 class="h5">Edit options and surcharges</h2><?php foreach($opts as $o):?><div class="card p-2 mb-2"><form method="post" class="row g-2 align-items-center"><?=csrf_field()?><input type="hidden" name="action" value="custom_option_save"><input type="hidden" name="option_id" value="<?=$o['option_id']?>"><div class="col-md-3"><select class="form-select" name="type_id"><?php foreach($types as $t):?><option value="<?=$t['type_id']?>" <?=$t['type_id']==$o['type_id']?'selected':''?>><?=e($t['type_name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><input class="form-control" name="option_name" value="<?=e($o['option_name'])?>"></div><div class="col-md-3"><input class="form-control" type="number" min="0" step=".01" name="additional_cost" value="<?=$o['additional_cost']?>"></div><div class="col-md-2"><button class="btn btn-sm btn-outline-dark">Save</button></div><input type="hidden" name="description" value="<?=e($o['description']??'')?>"><input type="hidden" name="preview_color" value="<?=e($o['preview_color']??'')?>"><input type="hidden" name="preview_layer_key" value="<?=e($o['preview_layer_key'])?>"></form><form method="post" enctype="multipart/form-data" class="row g-2 align-items-center mt-1"><?=csrf_field()?><input type="hidden" name="action" value="custom_option_save"><input type="hidden" name="option_id" value="<?=$o['option_id']?>"><input type="hidden" name="type_id" value="<?=$o['type_id']?>"><input type="hidden" name="option_name" value="<?=e($o['option_name'])?>"><input type="hidden" name="additional_cost" value="<?=$o['additional_cost']?>"><input type="hidden" name="description" value="<?=e($o['description']??'')?>"><div class="col-md-4"><label>Color<input class="form-control form-control-color" type="color" name="preview_color" value="<?=e($o['preview_color']?:'#ffffff')?>"></label></div><div class="col-md-4"><label>Layer<select class="form-select" name="preview_layer_key"><?php foreach(['main','overlay','material','component'] as $layer):?><option <?=$o['preview_layer_key']===$layer?'selected':''?>><?=$layer?></option><?php endforeach;?></select></label></div><div class="col-md-4"><label>Replace preview image<input class="form-control" type="file" name="preview_image" accept="image/png,image/webp,image/jpeg"></label></div><div class="col-12 small text-muted"><?=$o['preview_image_path']?'Current: '.e($o['preview_image_path']):'No image asset. Solid color is used for main preview layer.'?></div><button class="btn btn-sm btn-outline-dark col-auto">Save preview</button></form><form method="post" class="text-end"><?=csrf_field()?><input type="hidden" name="action" value="custom_option_toggle"><input type="hidden" name="option_id" value="<?=$o['option_id']?>"><button class="btn btn-sm btn-link"><?=$o['is_active']?'Disable':'Enable'?></button></form></div><?php endforeach;?>
    <h2 class="h5 mt-4">Assign options to a product</h2><form method="get" class="mb-2"><input type="hidden" name="page" value="customization-admin"><select class="form-select" name="product_id" onchange="this.form.submit()"><?php foreach($products as $p):?><option value="<?=$p['product_id']?>" <?=$pid===$p['product_id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form><form method="post" class="card p-3 mb-2"><?=csrf_field()?><input type="hidden" name="action" value="preview_kind_save"><input type="hidden" name="product_id" value="<?=$pid?>"><label>Illustration shape<select class="form-select" name="customization_preview_kind"><?php foreach(['generic'=>'Generic image fallback','sofa'=>'Sofa','coffee_table'=>'Coffee table','bed'=>'Bed','dining_table'=>'Dining table'] as $kind=>$label):?><option value="<?=$kind?>" <?=$previewKind===$kind?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button class="btn btn-outline-dark mt-2">Save preview shape</button></form><form method="post" class="card p-3"><?=csrf_field()?><input type="hidden" name="action" value="product_options_save"><input type="hidden" name="product_id" value="<?=$pid?>"><?php foreach($opts as $o):?><label class="d-block"><input type="checkbox" name="option_ids[]" value="<?=$o['option_id']?>" <?=in_array((int)$o['option_id'],$assigned,true)?'checked':''?> <?=$o['is_active']?'':'disabled'?>> <?=e($o['type_name'])?>: <?=e($o['option_name'])?> · <?=money($o['additional_cost'])?> <?=$o['is_active']?'':'(disabled)'?></label><?php endforeach;?><button class="btn btn-primary mt-2">Save product options</button></form>
    <h2 class="h5 mt-4">Dimensions and price formulas</h2><p class="small text-muted">Leave a dimension unchecked if the customer should not configure it. Range boundaries are half-open; the highest configured maximum is included.</p><form method="post" class="card p-3"><?=csrf_field()?><input type="hidden" name="action" value="dimension_rules_save"><input type="hidden" name="product_id" value="<?=$pid?>"><?php foreach(['width'=>'Width','height'=>'Height','depth'=>'Depth'] as $d=>$label):$r=$dimensionRules[$d]??null;?><fieldset class="border rounded p-2 mb-2"><legend class="float-none w-auto px-1 fs-6"><label><input type="checkbox" name="enabled[<?=$d?>]" <?=($r?'checked':'')?>> <?=$label?></label></legend><div class="row g-2"><div class="col-6 col-md-3"><label>Minimum cm<input class="form-control" type="number" step=".1" name="min[<?=$d?>]" value="<?=$r['min_cm']??'50'?>"></label></div><div class="col-6 col-md-3"><label>Maximum cm<input class="form-control" type="number" step=".1" name="max[<?=$d?>]" value="<?=$r['max_cm']??'200'?>"></label></div><div class="col-6 col-md-3"><label>Default cm<input class="form-control" type="number" step=".1" name="default[<?=$d?>]" value="<?=$r['default_cm']??'100'?>"></label></div><div class="col-6 col-md-3"><label>Step cm<input class="form-control" type="number" min=".1" step=".1" name="step[<?=$d?>]" value="<?=$r['step_cm']??'1'?>"></label></div><div class="col-6 col-md-6"><label>Pricing formula<select class="form-select" name="mode[<?=$d?>]"><?php foreach(['none'=>'No added charge','per_cm'=>'Per cm above default','fixed'=>'Fixed if changed','percentage'=>'Percent of base if changed','ranges'=>'Configured price ranges','material_usage'=>'Material usage per extra 100 cm'] as $mode=>$modeLabel):?><option value="<?=$mode?>" <?=($r['pricing_mode']??'none')===$mode?'selected':''?>><?=$modeLabel?></option><?php endforeach;?></select></label></div><div class="col-6 col-md-6"><label>Price amount<input class="form-control" type="number" min="0" step=".01" name="amount[<?=$d?>]" value="<?=$r['price_amount']??0?>"></label></div></div></fieldset><?php endforeach;?><button class="btn btn-primary">Save dimension rules</button></form>
    <?php foreach($dimensionRules as $d=>$r):if($r['pricing_mode']!=='ranges')continue;$rr=db()->prepare('SELECT range_id,min_cm,max_cm,additional_cost FROM product_dimension_price_ranges WHERE product_id=? AND dimension_name=? ORDER BY min_cm');$rr->execute([$pid,$d]);?><h3 class="h6 mt-3"><?=ucfirst($d)?> price ranges</h3><?php foreach($rr as $x):?><div class="d-flex justify-content-between border-bottom py-1"><span><?=$x['min_cm']?> to <?=$x['max_cm']?> cm · <?=money($x['additional_cost'])?></span><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="dimension_range_delete"><input type="hidden" name="product_id" value="<?=$pid?>"><input type="hidden" name="range_id" value="<?=$x['range_id']?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form></div><?php endforeach;?><form method="post" class="row g-2 mt-1"><?=csrf_field()?><input type="hidden" name="action" value="dimension_range_save"><input type="hidden" name="product_id" value="<?=$pid?>"><input type="hidden" name="dimension_name" value="<?=$d?>"><div class="col-4"><input class="form-control" type="number" step=".1" name="min_cm" placeholder="From cm" required></div><div class="col-4"><input class="form-control" type="number" step=".1" name="max_cm" placeholder="To cm" required></div><div class="col-3"><input class="form-control" type="number" min="0" step=".01" name="additional_cost" placeholder="Extra $" required></div><div class="col-1"><button class="btn btn-outline-dark">+</button></div></form><?php endforeach;?></section></div><?php return true;
}

function render_request_quote_summary(): void {
    $requests=db()->query('SELECT request_status,COUNT(*) total FROM custom_requests GROUP BY request_status')->fetchAll();
    $quotes=db()->query('SELECT COUNT(*) decided,SUM(status="Accepted") accepted FROM quotations WHERE status IN ("Accepted","Rejected")')->fetch();
    $rate=(int)$quotes['decided']?round((int)$quotes['accepted']/(int)$quotes['decided']*100):0;
    ?><div class="row g-3 mb-4"><div class="col-lg-8"><div class="card p-3"><h2 class="h5">Custom requests by status</h2><?php if(!$requests):?><div class="empty">No custom requests yet.</div><?php endif;?><?php foreach($requests as $r):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e($r['request_status'])?></span><b><?=$r['total']?></b></div><?php endforeach;?></div></div><div class="col-lg-4"><div class="card p-3 h-100"><h2 class="h5">Quotation acceptance</h2><strong class="display-6"><?=$rate?>%</strong><p class="mb-0"><?=e($quotes['accepted']??0)?> accepted from <?=e($quotes['decided'])?> decided quotations</p></div></div></div><?php
}


